    private double milk;

    public Mammal(String name, double milk) {
        super(name);
        this.milk = milk;
    }

    public double getMilk() {
        return milk;
    }

    public String say() {
        return "יונק";
    }
}

public class Dog extends Mammal {
    private int bones;

    public Dog(String name, double milk, int bones) {
        super(name, milk);
        this.bones = bones;
    }

    public int getBones() {
        return bones;
    }

    public String say() {
        return "כלב";
    }
}

public class Bird extends Animal {
    public Bird(String name) {
        super(name);
    }

    public String fly() {
        return getName() + " עף";
    }
}

