public static String check(Object got, Object expected) {
    String g = String.valueOf(got);
    String e = String.valueOf(expected);
    if (g.equals(e)) {
        return "נכון";
    }
    return "לא נכון — התקבל " + g + ", צריך להתקבל " + e;
}

public static String checkVerdict(String got, int key) {
    String[] all = { "תקין", "שגיאת הידור", "שגיאת ריצה" };
    String g = got == null ? "null" : got.trim();
    if (g.equals(all[key % 3])) {
        return "נכון";
    }
    if (!g.equals(all[0]) && !g.equals(all[1]) && !g.equals(all[2])) {
        return "לא נכון — התקבל " + g + " (התשובה היא תקין, שגיאת הידור או שגיאת ריצה)";
    }
    return "לא נכון — התקבל " + g;
}

