System.out.println("סעיף ז, בדיקה 2 (ציפור): " + check(safeBones(a), 0));
System.out.println("סעיף ז, בדיקה 3 (יונק שאינו כלב): " + check(safeBones(new Mammal("Numa", 2.5)), 0));

